module Arkham.Enemy.RegistrySpec (spec) where

import Arkham.Enemy.CardDefs.Standalone qualified as Enemies
import Arkham.Enemy.Types (allEnemyCards)
import Arkham.Matcher (EnemyMatcher (EnemyWithId), enemyIsExact)
import Data.Map.Strict qualified as Map
import Data.Set qualified as Set
import Data.UUID (nil)
import TestImport.New

-- allEnemyCardBuilders is generated by cards-discover from the builders' type
-- signatures, so a builder it cannot read is silently left out and the first
-- spawn of that card dies with "Unknown enemy (lookupEnemy)". The Replicating
-- Aberrations were declared with multi-name signatures and went missing that
-- way, crashing The Blob That Ate Everything ELSE.
--
-- Map.member and unCardCode rather than elem or (==): Eq CardCode deliberately
-- matches the two sides of a card ("89010a" == "89010b"), while the registry
-- is a Map keyed by the exact Ord.
spec :: Spec
spec = describe "enemy registry" do
  it "registers every Replicating Aberration builder" $ io do
    [code | code <- aberrations, not (Map.member code allEnemies)] `shouldBe` []
    enemy <- evaluate $ lookupEnemy "89010b" (EnemyId nil) nullCardId
    unCardCode (toCardCode enemy) `shouldBe` "89010b"

  it "backs every enemy card def with a builder" $ io do
    [ code
      | code <- Map.keys allEnemyCards
      , not (Map.member code allEnemies)
      , not (Set.member code knownUnbuilt)
      ]
      `shouldBe` []

  -- Each allowlisted code must still be a def without a builder; once either
  -- stops being true the entry is stale and has to go.
  it "keeps the unbuilt allowlist current" $ io do
    [ code
      | code <- Set.toList knownUnbuilt
      , not (Map.member code allEnemyCards) || Map.member code allEnemies
      ]
      `shouldBe` []

  it "spawns a Replicating Aberration in The Blob That Ate Everything"
    . scenarioTest "85001"
    $ \self -> do
      location <- testLocation
      self `moveTo` location
      run
        $ ScenarioSpecific "blobSpawnAberration"
        $ toJSON (toCardCode Enemies.replicatingAberrationB, toTarget location)
      -- Exact: plain enemyIs would also accept the other sides of 89010.
      assertAny $ enemyIsExact Enemies.replicatingAberrationB

  -- Only Replicating Aberration A discards the enemy it replicates. B is a
  -- distinct card even though Eq CardCode pairs "89010b" with "89010a".
  it "discards the replicated enemy only for Replicating Aberration A"
    . scenarioTest "85001"
    $ \self -> do
      location <- testLocation
      self `moveTo` location
      replicatedByB <- testEnemy
      replicatedByB `spawnAt` location
      run
        $ ScenarioSpecific "blobSpawnAberration"
        $ toJSON (toCardCode Enemies.replicatingAberrationB, toTarget replicatedByB)
      assertAny $ enemyIsExact Enemies.replicatingAberrationB
      assertAny $ EnemyWithId replicatedByB.id

      replicatedByA <- testEnemy
      replicatedByA `spawnAt` location
      run
        $ ScenarioSpecific "blobSpawnAberration"
        $ toJSON (toCardCode Enemies.replicatingAberrationA, toTarget replicatedByA)
      assertAny $ enemyIsExact Enemies.replicatingAberrationA
      assertNone $ EnemyWithId replicatedByA.id

-- TestImport's expectations are lifted; pin the plain hspec examples to IO.
io :: IO () -> IO ()
io = id

aberrations :: [CardCode]
aberrations = ["89010a", "89010b", "89010c", "89010d", "89010e", "89010f", "89010g", "89010h", "89010i"]

-- Enemy card defs that legitimately have no builder of their own. A Set so
-- that membership is exact rather than side-matching.
knownUnbuilt :: Set CardCode
knownUnbuilt =
  Set.fromList
    -- Epic Multiplayer variants with no implementation yet. Nothing can spawn
    -- them: no scenario gathers LabyrinthsOfLunacyEpicMultiplayer or
    -- MachinationsThroughTimeEpicMultiplayer, and no code names these defs.
    [ "70049" -- Eixodolon's Pet: You Are Not Its First Victim, Or Its Last
    , "70051" -- The Jailor
    , "87037" -- Edwin Bennet: Envious Rival (flip side of 87037b)
    ]
